ServerEvents.recipes(event => {
  let n = 0
  for (let [alias, canon] of DEDUPE) {
    if (!Item.exists(alias) || !Item.exists(canon)) continue
    event.replaceOutput({}, alias, canon)
    event.replaceInput({}, alias, canon)
    event.shapeless(canon, [alias]).id('diaithir_dedupe:convert/' + alias.replace(':', '/'))
    n++
  }
  console.info('[dedupe] ' + n + ' aliases remapped')
})

// KubeJS keeps the original recipe JSON until the end of the event, so the live check reads the loaded recipe displays one tick after load.
let dedupeChecked = false
ServerEvents.tick(event => {
  if (dedupeChecked) return
  dedupeChecked = true
  let names = new Set(DEDUPE.map(p => p[0])), left = 0
  for (let h of event.server.getRecipeManager().getRecipes()) {
    if (String(h.id()).indexOf('diaithir_dedupe:convert/') >= 0) continue
    let m = String(h.value().display()).match(/item [/] ([a-z0-9_.-]+:[a-z0-9_/.-]+)\]/g) || []
    for (let x of m) if (names.has(x.slice(7, -1))) { left++; console.warn('[dedupe] alias still in ' + h.id() + ': ' + x.slice(7, -1)); break }
  }
  console.info('[dedupe] recipes still naming an alias: ' + left)
})
